  {q:"What does the Result<T, E> type represent?", choices:["A random number","Either a success value (Ok) or an error (Err)","A type of loop","A mutable reference"], correct:1, diff:"medium", exp:"Result is Rust's primary error-handling enum, forcing explicit handling of the Ok or Err case."},
  {q:"What is a 'crate' in Rust?", choices:["A syntax error","A compilation unit / package of Rust code","A type of loop","A memory allocator"], correct:1, diff:"medium", exp:"A crate is the smallest unit of code distribution, roughly equivalent to a library or package."},
  {q:"What does the '&' symbol typically indicate in Rust?", choices:["A pointer to freed memory","A reference (borrow) to a value","Bitwise AND only","A macro invocation"], correct:1, diff:"medium", exp:"'&' creates a reference, borrowing a value without taking ownership of it."},
  {q:"What is the Option<T> type used for?", choices:["Configuration settings","Representing a value that might be present (Some) or absent (None)","Defining optional function parameters","Storing error messages only"], correct:1, diff:"medium", exp:"Option<T> replaces null with an explicit Some(value) or None, forcing handling of the absent case at compile time."},
  {q:"What does 'match' do in Rust?", choices:["Compares two strings for equality only","Pattern-matches a value against possible cases exhaustively","Imports a module","Starts a loop"], correct:1, diff:"medium", exp:"match compares a value against patterns and the compiler enforces that all possible cases are handled."},
  {q:"What is the borrow checker responsible for?", choices:["Formatting code","Enforcing Rust's ownership and borrowing rules at compile time","Managing the cargo registry","Compiling to machine code"], correct:1, diff:"hard", exp:"The borrow checker statically verifies references don't outlive their data and that mutable/immutable borrows don't conflict, preventing data races and dangling pointers."},
  {q:"What is the difference between a mutable and immutable borrow rule in Rust?", choices:["No difference","You can have either multiple immutable borrows OR one mutable borrow at a time, not both","You can always have both simultaneously","Mutable borrows are not allowed at all"], correct:1, diff:"hard", exp:"Rust enforces at compile time that a value can have many readers (&T) or exactly one writer (&mut T), never both at once."},
  {q:"What does 'unsafe' allow in Rust?", choices:["Faster compilation only","Operations the compiler can't verify are memory-safe, like raw pointer dereferencing","Skipping all error handling","Ignoring the type system entirely"], correct:1, diff:"hard", exp:"unsafe blocks allow specific operations (raw pointers, FFI, etc.) that bypass some compiler safety checks, placing responsibility on the programmer."},
  {q:"What is a lifetime in Rust used for?", choices:["Measuring program runtime","Annotating how long references remain valid relative to each other","Garbage collection timing","Thread scheduling priority"], correct:1, diff:"hard", exp:"Lifetimes are compiler annotations ensuring references don't outlive the data they point to, preventing dangling references."},
  {q:"What trait must a type implement to be duplicated with simple assignment instead of being moved?", choices:["Clone","Copy","Duplicate","Send"], correct:1, diff:"hard", exp:"Types implementing the Copy trait (like i32) are copied bit-for-bit on assignment instead of being moved."},
  {q:"What does the Send trait indicate about a type?", choices:["It can be printed","It's safe to transfer ownership of it across thread boundaries","It implements iteration","It can be serialized to JSON"], correct:1, diff:"hard", exp:"Send marks a type as safe to move to another thread; most types are Send automatically unless they contain non-thread-safe internals."},
  {q:"What is a trait object (e.g. dyn Trait) used for?", choices:["Compile-time only generics","Dynamic dispatch to call trait methods on different concrete types through a common interface","Defining structs","Memory allocation"], correct:1, diff:"hard", exp:"dyn Trait enables runtime polymorphism, letting code work with different concrete types behind a shared trait interface."},
  {q:"What does the '?' operator do after a function call returning Result?", choices:["Prints a question to the console","Propagates an Err early by returning it from the current function, or unwraps Ok","Checks if a value is null","Starts a conditional block"], correct:1, diff:"hard", exp:"The ? operator returns the error early from the enclosing function if the Result is Err, otherwise unwraps the Ok value."}
